"""
Generate the catalog index from the model entries, so it can't drift from the code.

    python3 -m ode_catalog.index
"""

from pathlib import Path

from ode_catalog import CATALOG

INDEX_PATH = Path(__file__).parent / "INDEX.md"


def _source(entry):
    return entry.reference.citation if entry.reference else "Not from a publication"


def _unit(entry):
    return entry.time_unit or "not recorded"


def render_index():
    """Return the catalog index as Markdown."""
    lines = [
        "# Model catalog",
        "",
        "Generated by `python3 -m ode_catalog.index`. Don't edit this file by hand.",
        "",
        "| Model | Title | States | Time unit | Status | Scenarios |",
        "|---|---|---|---|---|---|",
    ]
    for name, entry in sorted(CATALOG.items()):
        states = ", ".join(entry.spec.state_names)
        scenarios = ", ".join(scenario.name for scenario in entry.scenarios)
        lines.append(
            f"| [{name}]({name}/README.md) | {entry.title} | {states} | {_unit(entry)} "
            f"| {entry.status.value} | {scenarios} |"
        )
    lines += ["", "## Sources and evidence", ""]
    for name, entry in sorted(CATALOG.items()):
        lines += [
            f"### {name}",
            "",
            f"- **Source:** {_source(entry)}",
            f"- **Evidence:** {entry.evidence or 'The contract tests pass.'}",
            "",
        ]
    return "\n".join(lines)


def main():
    INDEX_PATH.write_text(render_index(), encoding="utf-8")
    print(f"Wrote {INDEX_PATH}")


if __name__ == "__main__":
    main()
